create extension if not exists pgcrypto;
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.albums (id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null, description text, cover_url text, sort_order integer not null default 0, published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.photos (id uuid primary key default gen_random_uuid(), album_id uuid references public.albums(id) on delete set null, title text, description text, image_path text not null, sort_order integer not null default 0, featured boolean not null default false, published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.projects (id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null, description text not null default '', body text, technologies text[] not null default '{}', links jsonb not null default '[]', image_paths text[] not null default '{}', date date, category text not null default 'Coding', featured boolean not null default false, published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.site_settings (key text primary key, value text not null default '', updated_at timestamptz not null default now());
alter table public.admin_users enable row level security; alter table public.albums enable row level security; alter table public.photos enable row level security; alter table public.projects enable row level security; alter table public.site_settings enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.admin_users where user_id = auth.uid()) $$;
create policy "albums are public when published" on public.albums for select using (published or public.is_admin()); create policy "photos are public when published" on public.photos for select using (published or public.is_admin()); create policy "projects are public when published" on public.projects for select using (published or public.is_admin()); create policy "settings are readable" on public.site_settings for select using (true);
create policy "admins manage albums" on public.albums for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage photos" on public.photos for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage projects" on public.projects for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage settings" on public.site_settings for all using (public.is_admin()) with check (public.is_admin());
insert into storage.buckets (id, name, public) values ('portfolio-images', 'portfolio-images', true) on conflict (id) do nothing;
create policy "portfolio images are readable" on storage.objects for select using (bucket_id = 'portfolio-images'); create policy "admins upload images" on storage.objects for insert with check (bucket_id = 'portfolio-images' and public.is_admin()); create policy "admins update images" on storage.objects for update using (bucket_id = 'portfolio-images' and public.is_admin()); create policy "admins delete images" on storage.objects for delete using (bucket_id = 'portfolio-images' and public.is_admin());
